const contentTypes = {
  ".css": "text/css; charset=utf-8",
  ".html": "text/html; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".webp": "image/webp",
  ".woff2": "font/woff2",
};

const files = {"/index.html":"","/solutions.html":"","/about.html":"","/contact.html":"","/separation-kernel-hypervisor.html":"","/globe.html":"","/iot-solutions.html":"","/cybersecurity-solutions.html":"","/cybersecurity-visual.html":"","/iot-visual.html":"","/information-security-consulting.html":"","/consulting-visual.html":"","/styles.css":"","/service-page.css":"","/main.js":"","/why-globe.js":"","/service-page.js":"","/assets/logo.webp":"","/fonts/GeistPixel-Circle.woff2":""};

export default {
  async fetch(request) {
    const url = new URL(request.url);
    const pathname = url.pathname === "/" ? "/index.html" : url.pathname;
    const asset = files[pathname];

    if (!asset) {
      return new Response("Not found", { status: 404 });
    }

    const extension = pathname.slice(pathname.lastIndexOf("."));
    return new Response(Uint8Array.from(atob(asset), (character) => character.charCodeAt(0)), {
      headers: {
        "Cache-Control": pathname === "/index.html" ? "no-cache" : "public, max-age=31536000, immutable",
        "Content-Type": contentTypes[extension] || "application/octet-stream",
      },
    });
  },
};
